/* Persisted values are rendered as escaped text; mutations always use the API. */
"use strict";
const main = document.getElementById("main");
const labels = {investigating:"Investigating", awaiting_approval:"Needs approval", pending_approval:"Needs approval", action_ready:"Action ready", pending_verification:"Pending verification", monitoring:"Monitoring", resolved:"Resolved", closed:"Closed", reopened:"Reopened", incomplete:"Uncertain", unknown:"Unknown", answered:"Answered", not_applicable:"Not applicable", ready:"Ready", connected:"Connected", cached:"Cached", configured:"Configured", disabled:"Disabled", missing:"Missing", unavailable:"Unavailable", not_checked:"Not checked", running:"In progress", failed:"Failed"};
const questions = ["What happened?","How abnormal is it?","Is the data reliable?","Is this meter alone affected?","Are related meters affected?","Can weather explain the change?","Could customer behavior explain it?","Could solar, EV, or load changes explain it?","Is there an upstream mismatch?","What are the most plausible hypotheses?","How confident is the system?","What evidence supports or contradicts each hypothesis?","What should happen next?","Does the action require human approval?","Did the condition improve afterward?","What is the Revenue at Risk in JOD?","Are there precedents or repeated patterns?","What is its triage priority?"];
let generation=0, busy=false, queueItems=[],queueMeta={investigated_total:0,legacy_total:0},queueView="investigations";
let refreshingLive=false, liveRequest=0, refreshRequired=false, noticeTimer;
let filters={search:"",status:"",priority:"",sort:"priority"};
const DEMO_METERS=["SC2-M1","SC2-M2","SC2-M3"],DEMO_TOTAL=9;
let live={phase:"ready",progress:0,total:DEMO_TOTAL,caseId:null,detail:null,trace:null,stream:[],error:null,ready:false};
const THEME_KEY="meterdetective-theme";
const activityLabels={
  get_meter_profile:["Meter details reviewed","The investigation confirmed which customer and network information applies."],
  get_reading_window:["Recent readings gathered","The system collected enough history to compare the new reading fairly."],
  validate_reading_quality:["Reading quality checked","Reliable readings are required before a change is treated as a real anomaly."],
  calculate_baseline:["Normal usage pattern calculated","Recent behavior was compared with the meter's usual pattern."],
  detect_anomaly:["Unusual reading checked","The latest reading was tested against validated anomaly thresholds."],
  forecast_expected_usage:["Expected usage estimated","Historical readings provide an evidence-based comparison point."],
  select_dynamic_peers:["Comparable meters selected","Only meters with relevant characteristics were used for comparison."],
  compare_with_peers:["Similar nearby meters compared","This helps distinguish an individual issue from a shared incident."],
  detect_isolation_forest_anomaly:["A second anomaly check completed","An independent method was used to challenge the initial finding."],
  calculate_anomaly_severity:["Technical severity assessed","Multiple anomaly signals were combined into a consistent severity assessment."],
  get_connected_assets:["Network connections checked","The system identified equipment shared by the affected meters."],
  detect_shared_incident:["Related readings compared","Matching changes across connected meters can indicate a shared problem."],
  calculate_energy_balance:["Transformer and meter totals compared","The upstream energy balance was checked for supporting evidence."],
  get_weather_context:["Weather context checked","Weather was considered as a possible explanation, without assuming causation."],
  analyze_customer_der_context:["Customer energy context reviewed","Solar, EV, and customer behavior were considered where data was available."],
  search_technical_knowledge:["Technical guidance reviewed","Relevant guidance was searched for a safe next step."],
  find_meter_precedents:["Previous cases compared","Relevant history was checked without treating the current case as its own precedent."],
  estimate_revenue_at_risk:["Operational impact assessed","The per-event revenue exposure was estimated from stored evidence."],
  calculate_triage_priority:["Response priority assessed","Severity, reach, evidence quality, and financial impact informed the queue position."],
  create_case_and_record_investigation:["Case updated","Evidence, explanations, and findings were saved for later review."],
  propose_action_for_approval:["Recommended next step prepared","A safe next step was proposed and held for human approval."]
};
const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const human = value => labels[value] || String(value || "Unknown").replaceAll("_"," ");
const badge = value => `<span class="badge ${esc(value)}">${esc(human(value))}</span>`;
const percent = value => Number.isFinite(value) ? `${Math.round(value*100)}%` : "Unknown";
const date = value => {if(!value)return "Not recorded";const d=new Date(/Z$|[+-]\d\d:\d\d$/.test(value)?value:value+"Z");return Number.isNaN(+d)?"Unknown":d.toLocaleString("en-GB",{timeZone:"UTC",hour12:false})+" UTC";};
// API Decimal amounts are serialized as strings; null/blank/booleans are not numbers.
const numeric = value => typeof value==="number" ? (Number.isFinite(value)?value:null) : typeof value==="string" && /^[-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?$/i.test(value.trim()) && Number.isFinite(Number(value)) ? Number(value) : null;
const money = value => numeric(value)!==null ? `${numeric(value).toLocaleString("en",{maximumFractionDigits:3})} JOD` : "Unknown";
const json = value => `<pre class="json">${esc(JSON.stringify(value,null,2))}</pre>`;
const panel = (title, body, id="") => `<section class="panel" ${id?`id="${id}"`:""}><div class="panel-body"><h2>${esc(title)}</h2>${body}</div></section>`;
const utcDate = value => new Date(typeof value === "string" && !/Z$|[+-]\d\d:\d\d$/.test(value) ? value+"Z" : value);
const age = value => {const ms=Date.now()-utcDate(value);return Number.isFinite(ms)?`${Math.max(0,Math.floor(ms/86400000))}d`:"Unknown";};
function notice(text,bad=false){clearTimeout(noticeTimer);const n=document.getElementById("notice");n.className=`notice ${bad?"bad":""}`;n.textContent=text;noticeTimer=setTimeout(()=>{n.textContent="";n.className="";},8000);}

function storedTheme(){try{const value=localStorage.getItem(THEME_KEY);return ["light","dark"].includes(value)?value:null;}catch{return null;}}
function applyTheme(theme,persist=false){const value=theme==="dark"?"dark":"light";document.documentElement.dataset.theme=value;if(persist)try{localStorage.setItem(THEME_KEY,value);}catch{/* Theme still applies for this tab. */}const control=document.getElementById("theme-toggle");if(control){const dark=value==="dark",label=dark?"Use light mode":"Use dark mode";control.setAttribute("aria-pressed",String(dark));control.setAttribute("aria-label",label);control.title=label;control.innerHTML=`<span aria-hidden="true">${dark?"☀":"☾"}</span><span>${dark?"Light mode":"Dark mode"}</span>`;}return value;}
function initializeTheme(){const media=window.matchMedia("(prefers-color-scheme: dark)"),saved=storedTheme();applyTheme(saved||(media.matches?"dark":"light"));const control=document.getElementById("theme-toggle");if(control)control.addEventListener("click",()=>applyTheme(document.documentElement.dataset.theme==="dark"?"light":"dark",true));media.addEventListener?.("change",event=>{if(!storedTheme())applyTheme(event.matches?"dark":"light");});}

async function api(path,body){const response=await fetch(`/api${path}`,body===undefined?{}:{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});let data;try{data=await response.json();}catch{throw Error("The server returned an unreadable response.");}if(!response.ok){const detail=typeof data.detail==="string"?data.detail:`Request failed (${response.status})`;const error=Error(detail);error.status=response.status;throw error;}return data;}
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function setNavigation(view){for(const name of ["live","cases","status"])document.getElementById(`nav-${name}`).classList.toggle("active",view===name);document.getElementById("breadcrumb").textContent={live:"/ Live monitoring",cases:"/ Case workspace",status:"/ System status"}[view]||"";}
function answerMap(detail){return new Map((detail.latest_report?.answers||[]).map(a=>[a.question_id,a]));}
function references(items){return (items||[]).map(e=>e.evidence_id?`<a href="#evidence-${esc(e.evidence_id)}" data-evidence="${esc(e.evidence_id)}">${esc(e.source || e.evidence_id)}</a>`:`<span>${esc(e.source)}</span>`).join(" · ")||"None recorded";}

function currentRecommendation(d){return d?.recommendations?.filter(r=>r.status!=="superseded").at(-1);}
function currentWorkflow(d){
  const recommendation=currentRecommendation(d),action=d?.actions?.find(a=>a.recommendation_id===recommendation?.id);
  const verification=(d?.case_events||[]).filter(e=>["verification_completed","verification_deferred"].includes(e.event_type)&&e.details?.action_id===action?.id).at(-1);
  const result=verification?answerMap(d).get(15)?.structured_values?.deterministic_status:null;
  const approvalPending=Boolean(recommendation?.requires_approval&&recommendation.status==="pending_approval"&&!recommendation.approval&&action?.status!=="completed");
  let title="Investigation active",help="Evidence is being reviewed before the next step.";
  if(["resolved","closed"].includes(d?.case?.status)){title=d.case.status==="resolved"?"Investigation resolved":"Investigation closed";help="The persisted case workflow is complete.";}
  else if(action?.status==="completed"){
    title=result?human(result):"Pending verification";
    help=result?"Follow-up evidence was evaluated by the verification engine.":"The simulated action is recorded. Follow-up readings are required to verify the outcome.";
  }else if(recommendation?.approval?.decision==="rejected"){title="Recommendation rejected";help="No action was executed. Review the next investigation step.";}
  else if(approvalPending){title="Human approval required";help="An operator must approve this simulated action before it can be recorded.";}
  else if(action?.status==="ready"){title=recommendation?.approval?.decision==="approved"?"Approved — simulated action ready":"Simulated action ready";help="The action has not been recorded yet. Approval is not verification.";}
  return {recommendation,action,verification,result,approvalPending,title,help};
}
function saveLivePlayback(){if(live.caseId)sessionStorage.setItem("meterdetective-live-playback",JSON.stringify({caseId:live.caseId,phase:live.phase,progress:live.progress,stream:live.stream}));}
function investigationPresence(){
  if(live.detail)return human(live.detail.case.status);
  if(live.caseId)return "Loading investigation…";
  if(["investigating_initial_anomaly","waiting_for_related_readings","updating_existing_case"].includes(live.phase))return "Investigation starting…";
  if(live.phase==="failed")return "Investigation state unavailable";
  return "No investigation open";
}
function verificationWindow(d,action){return action?.result?.verification_window||{start:d?.scenario?.repair_window_start,end:d?.scenario?.repair_window_end};}
function applyWorkflowResponse(d,response){
  if(!d)return;
  if(response.recommendation){
    const recommendation={...response.recommendation,approval:response.approval};
    d.recommendations=d.recommendations.map(item=>item.id===recommendation.id?recommendation:item);
  }
  if(response.action){
    const action={...response.action,result:response.action.result_json};
    d.actions=d.actions.map(item=>item.id===action.id?action:item);
  }
  if(response.case_id===d.case.id&&response.case_status)d.case.status=response.case_status;
}
function fixed(value,digits){return numeric(value)!==null?numeric(value).toFixed(digits):"Unknown";}
function captureForms(){return [...main.querySelectorAll("form[id]")].map(form=>({id:form.id,values:[...form.querySelectorAll("input[name],textarea[name]")].map(input=>[input.name,input.value])}));}
function restoreForms(forms){for(const form of forms){const target=document.getElementById(form.id);if(target)for(const [name,value] of form.values){const input=target.elements.namedItem(name);if(input)input.value=value;}}}

// Evidence/timestamp changes and polling errors are not operator form transitions.
function liveFormKey(d){
  const {recommendation:r,action,approvalPending}=currentWorkflow(d);
  return JSON.stringify([live.caseId,d?.case?.id,r?.id,action?.id,approvalPending,
    r?.approval?.decision,action?.status,["resolved","closed"].includes(d?.case?.status)]);
}
function updatePassive(selector,html){
  const target=main.querySelector(selector);
  // Future operator fields added to a passive panel must also survive polling.
  if(!target||target.matches("input,textarea,select,[contenteditable]")||target.querySelector("input,textarea,select,[contenteditable]"))return;
  if(target.innerHTML!==html)target.innerHTML=html;
}
function updateLivePassive(d){
  const [title,help]=livePhase(),state=currentWorkflow(d);
  updatePassive(".live-title h1",esc(liveHeading()));
  updatePassive(".case-reference",esc(d?`${d.meter_ids.length} affected meter${d.meter_ids.length===1?"":"s"}`:investigationPresence()));
  updatePassive("#demo-title",esc(title));
  updatePassive("#demo-title + p",esc(help));
  updatePassive(".progress-label",`<span>${live.progress?`Reading ${live.progress} of ${live.total}`:live.caseId?"Earlier replay progress unavailable":"Stream not started"}</span><span>${Math.round(live.progress/live.total*100)}%</span>`);
  const progress=main.querySelector(".progress");
  if(progress){progress.setAttribute("aria-valuenow",live.progress);progress.querySelector("span").style.width=`${live.progress/live.total*100}%`;}
  updatePassive("#play-demo",busy&&["playing_normal_readings","investigating_initial_anomaly","waiting_for_related_readings","updating_existing_case"].includes(live.phase)?"Stream playing…":"Play demonstration stream");
  updatePassive("#live-replay-error",live.error?`<div class="error inline-error" role="alert"><strong>The replay stopped safely.</strong><p>${esc(live.error)}</p><p>Reset the demonstration and try again. Existing historical cases were not removed.</p></div>`:"");
  updatePassive(".readiness",[["Database",live.ready||Boolean(d)],["Scenario data",live.ready||Boolean(d)],["Investigation workflow",Boolean(d)],["Recommendation recorded",Boolean(state.recommendation)]].map(([label,ready])=>`<span class="readiness-item ${ready?"ready":"waiting"}"><b aria-hidden="true">${ready?"✓":"○"}</b>${esc(label)} · ${ready?"Ready":"Waiting"}</span>`).join(""));
  updatePassive("#live-refresh-status",live.refreshError?`<div class="report-alert" role="status">Refresh unavailable: ${esc(live.refreshError)}. Showing the last stored case state; reload before another action.</div>`:"");
  if(!refreshRequired)updatePassive("#workflow-refresh-warning","");
  updatePassive(".live-stats",liveSummary(d).map(([label,value,note])=>`<div class="stat"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`).join(""));
  updatePassive("#live-stream",liveStream());
  for(const [id,title,body] of [
    ["live-activity","Investigation activity",liveActivity()],
    ["live-evidence","Evidence and investigation details",liveEvidence(d)],
    ["live-hypotheses","Competing explanations",liveHypotheses(d)],
    ["live-plan","Investigation plan",livePlans(d)],
    ["live-history","Case history",liveHistory(d)],
  ])updatePassive(`#${id} .panel-body`,`<h2>${esc(title)}</h2>${body}`);
  if(state.recommendation){
    const r=state.recommendation;
    updatePassive(".recommendation-head",`<div><h3>${esc(human(r.action_type))}</h3><p>${esc(r.rationale)}</p></div>${badge(r.risk)}`);
    updatePassive(".safety-callout",`<strong>${esc(state.title)}</strong><p>${esc(state.help)} Actions are simulated; no field equipment is controlled.</p>`);
    updatePassive(`#live-${r.id}-verification-result`,state.verification?outcome(answerMap(d).get(15)):"");
  }
  // Lock submissions on stale evidence without disabling or replacing editable drafts.
  main.querySelectorAll("button").forEach(button=>button.disabled=(busy||refreshRequired)&&(busy||button.id!=="refresh-live"));
  if(d)loadChart(d,generation);
}
function workflowRefreshWarning(message){
  const root=document.getElementById("live-workflow-controls")||document.getElementById("workflow-controls");
  if(!root)return;
  const html=`<div id="workflow-refresh-warning"><p class="report-alert">${esc(message)}</p><button id="reload-workflow">Reload case</button></div>`;
  // An unconfirmed submission is not an approval/state transition. Keep its draft too.
  if(root.querySelector("form"))root.insertAdjacentHTML("afterbegin",html);
  else {root.innerHTML=html;delete main.dataset.liveFormKey;}
  document.getElementById("reload-workflow").onclick=()=>route();
}

const statusCopy={
  ready:["Ready","✓"],connected:["Connected","✓"],cached:["Cached","↻"],
  configured:["Configured","✓"],disabled:["Disabled","○"],missing:["Missing","!"],
  unavailable:["Unavailable","!"],not_checked:["Not checked","○"],running:["In progress","↻"],failed:["Failed","!"],
};
function statusCard(title,component){const [label,icon]=statusCopy[component?.status]||[human(component?.status),"○"];return `<article class="status-card ${esc(component?.status||"unavailable")}"><div class="status-card-head"><span class="status-icon" aria-hidden="true">${icon}</span><div><h2>${esc(title)}</h2><span class="status-label">${esc(label)}</span></div></div><p>${esc(component?.detail||"Status details are unavailable.")}</p>${component?.count!==null&&component?.count!==undefined?`<small>${esc(component.count)} item${component.count===1?"":"s"} recorded</small>`:""}${component?.observed_at?`<small>Last observed ${esc(date(component.observed_at))}</small>`:""}${component?.critical?'<small class="critical-note">Required for the demonstration workflow</small>':""}</article>`;}
function renderStatus(data){setNavigation("status");const cards=[["Application",data.application],["Database",data.database],["Demonstration dataset",data.demonstration_dataset],["Technical knowledge base",data.knowledge_base],["Weather information",data.weather],["Optional narrative service",data.narrative_service],["Latest investigation",data.latest_investigation]];main.innerHTML=`<div class="title-row"><div><div class="kicker">READINESS · DEPENDENCIES · SAFE FALLBACKS</div><h1>System status</h1><p class="subtitle">A read-only view of the services and stored evidence used by this simulation.</p></div><button id="refresh-status">Refresh status</button></div><div class="status-summary"><strong>Simulation environment</strong><span>Checked ${esc(date(data.checked_at))}</span></div><div class="status-grid">${cards.map(([title,component])=>statusCard(title,component)).join("")}</div><section class="panel"><div class="panel-body"><h2>How to read this page</h2><div class="status-legend"><span>${badge("ready")} Available now</span><span>${badge("cached")} Safe stored information</span><span>${badge("disabled")} Optional and intentionally off</span><span>${badge("unavailable")} Investigation continues when safe</span></div><p class="muted">Database availability is required because MeterDetective does not silently switch to temporary storage. Weather and narrative generation are optional; unavailable optional evidence remains clearly labeled instead of being invented.</p></div></section>`;document.getElementById("refresh-status").onclick=()=>route();}
function renderStatusError(message){setNavigation("status");main.innerHTML=`<div class="error status-error" role="alert"><h1>System status is unavailable</h1><p>${esc(message)}</p><p>Live Operations and stored cases have not been changed.</p><button id="retry-status">Try again</button> <a href="#/live">Return to Live Operations</a></div>`;document.getElementById("retry-status").onclick=()=>route();}

async function route(quiet=false){if(busy||(quiet&&refreshingLive))return;const token=++generation;const hash=location.hash||"#/live",match=hash.match(/^#\/cases\/([^/]+)$/);if(hash==="#/status"){setNavigation("status");if(!quiet)main.innerHTML='<div class="empty" role="status">Checking system readiness…</div>';try{const data=await api("/status");if(token!==generation)return;renderStatus(data);}catch(error){if(token!==generation)return;if(quiet)notice(`Status refresh failed: ${error.message}`,true);else renderStatusError(error.message);}return;}if(hash==="#/live"){
  setNavigation("live");
  const saved=sessionStorage.getItem("meterdetective-live-case");
  if(!live.caseId&&saved){
    live.caseId=saved;live.phase="restored";
    try{const playback=JSON.parse(sessionStorage.getItem("meterdetective-live-playback"));if(playback?.caseId===saved){live.stream=playback.stream||[];live.progress=playback.progress||0;if(playback.phase==="complete")live.phase="complete";}}catch{/* Persisted case identity is still sufficient to refresh. */}
  }
  if(!quiet||!document.getElementById("play-demo"))renderLive();
  try{await refreshLiveCase(token);}catch(error){if(token!==generation)return;live.refreshError=error.message;refreshRequired=true;renderLive();notice(`Case refresh unavailable: ${error.message}. Stored state retained.`,true);}
  return;
}setNavigation("cases");if(!quiet)main.innerHTML='<div class="empty" role="status">Loading case workspace…</div>';try{if(match){const id=decodeURIComponent(match[1]);const detail=await api(`/cases/${encodeURIComponent(id)}`);if(token!==generation)return;refreshRequired=false;renderDetail(detail);if(detail.report_coverage?.has_report){loadTrace(id,token);loadChart(detail,token);}}else{let page=await api(`/triage/queue?limit=500&view=${queueView}`);let items=page.items;while(items.length<page.total){const next=await api(`/triage/queue?limit=500&view=${queueView}&offset=${items.length}`);if(!next.items.length)break;items=items.concat(next.items);}if(token!==generation)return;queueItems=items;queueMeta=page;if(quiet && document.getElementById("queue-body")){renderRows();return;}renderQueue();}}catch(error){if(token!==generation)return;if(quiet){notice(`Refresh failed: ${error.message}`,true);}else{main.innerHTML=`<div class="error" role="alert"><h1>Unable to load this view</h1><p>${esc(error.message)}</p><button id="retry">Try again</button> <a href="#/cases">Back to queue</a></div>`;document.getElementById("retry").onclick=()=>route();}}}
function livePhase(){
  if(live.phase==="complete"||live.phase==="restored"){
    const state=currentWorkflow(live.detail);
    if(["resolved","closed"].includes(live.detail?.case?.status))return [state.title,state.help];
    return [live.phase==="complete"?"Evidence stream complete":"Stored investigation",live.detail?state.title+". "+state.help:"Loading the stored investigation. Workflow completion has not been confirmed."];
  }
  return {ready:["Ready to demonstrate","Prepared readings will be replayed only when you start."],resetting:["Preparing the demonstration","Only previous Scenario 2 demonstration records are being reset."],playing_normal_readings:["Normal readings are arriving","Readings are being checked for anomalies."],investigating_initial_anomaly:["Checking incoming readings","Gathering initial evidence and preparing the investigation."],waiting_for_related_readings:["Waiting for related readings","The current explanation may change as new evidence arrives."],updating_existing_case:["New related evidence is being reviewed","The stored investigation will reflect the new evidence."],failed:["The demonstration needs attention","Accepted readings remain stored; the workflow is not complete."]}[live.phase]||["Live meter monitoring","Waiting for the next reading."];
}

function liveHeading(){if(!live.detail)return "Live meter monitoring";const reference=live.detail.meter_ids?.[0]?` · ${live.detail.meter_ids[0]}`:"";if(["resolved","closed"].includes(live.detail.case.status))return `${human(live.detail.case.status)} investigation${reference}`;return `Live investigation${reference}`;}
function evidenceByKind(d,kind){return d?.evidence?.filter(item=>item.kind===kind).at(-1);}
function available(value,fallback="Not enough evidence yet"){return value===null||value===undefined||value===""?fallback:value;}
function liveSummary(d){if(!d)return [["Affected meters","Not enough evidence yet",investigationPresence()],["Revenue at Risk","Not enough evidence yet","Calculated only from validated evidence"],["Leading explanation","Not enough evidence yet","Based on current evidence"],["Investigation coverage","0/18 recorded",investigationPresence()]];const f=d.financial_impact,h=[...(d.hypotheses||[])].sort((a,b)=>b.confidence-a.confidence)[0],coverage=d.report_coverage||{},answers=d.latest_report?.answers||[],unknown=answers.filter(a=>a.status==="unknown").length,pending=Math.max(0,18-(coverage.answered_count||0)-unknown);return [["Affected meters",String(d.meter_ids.length),d.plans?.at(-1)?.scope==="shared"?"Shared network area":"Individual meter area"],["Revenue at Risk",f?money(f.risk_jod.base):"Not enough evidence yet",f?"Per-event estimate · JOD":"Awaiting a validated calculation"],["Leading explanation · current evidence support",h?percent(h.confidence):"Not enough evidence yet",h?`${friendlyHypothesis(h.label)} · not proof of root cause`:"Confidence will appear with evidence"],["Investigation coverage",`${coverage.present_count||0}/18 recorded`,`${coverage.answered_count||0} answered · ${unknown} unknown · ${pending} pending`]];}
function friendlyHypothesis(label){const value=String(label||"").toLowerCase();if(value.includes("shared")||value.includes("transformer")||value.includes("upstream"))return "Shared transformer or network problem";if(value.includes("quality")||value.includes("communication")||value.includes("data"))return "Reading or communication problem";if(value.includes("customer")||value.includes("weather")||value.includes("solar")||value.includes("ev"))return "Explainable customer or environmental change";return "Individual meter problem";}
function planCard(plan,current=false){if(!plan)return '<p class="muted">No investigation plan has been recorded.</p>';return `<article class="plan-card ${current?"current":"earlier"}"><div class="plan-card-head"><strong>${current?"Current plan":"Earlier plan — no longer current"}</strong>${badge(current?"recommended":"superseded")}</div><p>${esc(plan.goal)}</p><ul>${(plan.steps||[]).map(step=>`<li>${esc(step)}</li>`).join("")}</ul><small>${current?"Supported by the latest stored evidence.":"Preserved so the decision history remains clear."}</small></article>`;}
function livePlans(d){const plans=d?.plans||[],current=plans.find(p=>p.status==="active")||plans.at(-1),earlier=[...plans].reverse().find(p=>p.id!==current?.id);if(!current)return '<div class="empty-state"><strong>No plan yet</strong><p>The investigation plan will appear after an anomaly is confirmed.</p></div>';const changed=Boolean(earlier&&current.evidence_ids?.length);return `${changed?'<div class="plan-change" role="status" tabindex="-1"><strong>New evidence changed the investigation plan.</strong><p>The current plan reflects the latest stored evidence. The earlier plan remains below for comparison.</p></div>':""}<div class="plan-compare">${earlier?planCard(earlier,false):""}${planCard(current,true)}</div>`;}
function liveHypotheses(d){if(!d?.hypotheses?.length)return '<div class="empty-state"><strong>No explanations compared yet</strong><p>Competing explanations will appear after the investigation starts.</p></div>';return `<div class="hypothesis-grid">${d.hypotheses.slice(0,4).map(h=>{const history=h.update_history||[],previous=history.length>1?history.at(-2)?.confidence:null,change=typeof previous==="number"?h.confidence-previous:null,direction=change===null?"No previous comparison":Math.abs(change)<.005?"Evidence support unchanged":change>0?"Evidence support increased":"Evidence support decreased";return `<article class="hypothesis-card"><div class="hypothesis-title"><h3>${esc(friendlyHypothesis(h.label))}</h3><strong class="support-score"><small>Current evidence support:</small> ${percent(h.confidence)}</strong></div><div class="confidence" aria-label="Evidence support ${percent(h.confidence)}"><span style="width:${Math.max(0,Math.min(100,h.confidence*100))}%"></span></div><p>${esc(direction)} as evidence arrived.</p><div class="evidence-counts"><span>${(h.supporting_evidence||[]).length} supporting</span><span>${(h.contradicting_evidence||[]).length} contradicting</span></div><details><summary>Review supporting and contradicting evidence</summary><p>Evidence support is not proof of root cause.</p><p>Supports: ${esc((h.supporting_evidence||[]).join(", ")||"None recorded")}</p><p>Contradicts: ${esc((h.contradicting_evidence||[]).join(", ")||"None recorded")}</p></details></article>`;}).join("")}</div><p class="confidence-note">Evidence support is not proof of root cause and may change when new readings arrive.</p>`;}
function evidenceFinding(item){if(!item)return "Not enough evidence yet";const v=item.value||{};if(item.kind==="data_quality")return v.reliable===true?`Readings passed quality checks with a score of ${available(v.quality_score)} out of 100.`:v.reliable===false?"The available readings have quality limitations.":"Reading reliability is unknown.";if(item.kind==="peer_comparison")return v.status==="answered"?`${available(v.peer_count)} comparable meter readings were available for comparison.`:"Comparable readings were not sufficient.";if(item.kind==="shared_incident")return v.status==="answered"?`${available(v.affected_count)} of ${available(v.answered_count)} assessed related meters show the pattern.`:"Related-meter evidence is not yet sufficient.";if(item.kind==="energy_balance")return v.status==="answered"?"A transformer-to-meter comparison was completed and saved.":"Transformer evidence was unavailable; the investigation continued.";if(item.kind==="technical_knowledge")return v.status==="answered"?`${(v.citations||[]).length} relevant guidance source(s) were found.`:"No suitable guidance was available; the investigation continued.";if(item.kind==="financial_impact")return v.status==="answered"?"A per-event revenue estimate was calculated from the stored tariff and readings.":"A supported financial estimate could not be calculated.";return "The result was recorded as evidence for this investigation.";}
function liveEvidence(d){if(!d)return '<div class="empty-state"><strong>Evidence will appear here</strong><p>The screen shows readable findings instead of technical inputs or raw data.</p></div>';const rows=[["data_quality","Checked reading quality","Confirm that the anomaly is based on reliable data"],["peer_comparison","Compared similar meters","Determine whether the event is isolated"],["shared_incident","Compared related readings","Look for a shared network pattern"],["energy_balance","Compared transformer and meter totals","Test the upstream explanation"],["technical_knowledge","Reviewed technical guidance","Identify a safe evidence-backed response"],["financial_impact","Estimated operational impact","Support prioritization"]];return `<div class="friendly-table"><div class="friendly-row friendly-head"><span>Investigation step</span><span>Why it was needed</span><span>What was found</span><span>Status</span></div>${rows.map(([kind,title,why])=>{const item=evidenceByKind(d,kind);return `<div class="friendly-row"><strong>${esc(title)}</strong><span>${esc(why)}</span><span>${esc(evidenceFinding(item))}</span><span>${badge(item?item.value?.status||"completed":"waiting")}</span></div>`;}).join("")}</div>`;}
function friendlyDuration(ms){if(!Number.isFinite(ms))return "Time not recorded";if(ms<1000)return "Less than a second";return `${(ms/1000).toFixed(1)} seconds`;}
function liveActivity(){const tools=(live.trace?.runs||[]).flatMap(run=>run.tools||[]),latest=new Map();tools.forEach(tool=>{if(activityLabels[tool.name])latest.set(tool.name,tool);});if(!latest.size)return '<div class="empty-state"><strong>Monitoring is active</strong><p>Investigation steps will appear automatically when an unusual reading is detected.</p></div>';return `<div class="activity-list">${[...latest].map(([name,tool])=>{const copy=activityLabels[name],status=tool.status==="succeeded"?"Completed":tool.status==="running"?"In progress":"Unavailable — investigation continued";return `<div class="activity-item"><span class="activity-icon" aria-hidden="true">${tool.status==="succeeded"?"✓":"!"}</span><div><div class="activity-title"><strong>${esc(copy[0])}</strong>${badge(tool.status==="succeeded"?"completed":tool.status==="running"?"running":"unavailable")}</div><p>${esc(copy[1])}</p><small>${esc(friendlyDuration(tool.latency_ms))} · ${esc(status)}</small></div></div>`;}).join("")}</div>`;}
function liveStream(){if(!live.stream.length&&live.caseId)return '<div class="empty-state"><strong>Stored investigation loaded</strong><p>The earlier replay log is unavailable in this tab. Persisted case evidence remains available below.</p></div>';if(!live.stream.length)return '<div class="empty-state"><strong>No readings played yet</strong><p>Select Play demonstration stream to watch readings arrive and trigger an investigation automatically.</p></div>';return `<div class="stream-list">${live.stream.map(item=>`<div class="stream-item ${esc(item.kind)}"><span class="stream-dot" aria-hidden="true"></span><div><strong>${esc(item.label)}</strong><small>${esc(item.meter)} · ${esc(item.time)} UTC</small></div><span>${esc(item.value)}</span></div>`).join("")}</div>`;}
function liveHistory(d){const state=currentWorkflow(d),steps=[["Trigger detected",Boolean(d)],["Investigation started",Boolean(d)],["Evidence collected",Boolean(d?.evidence?.length)],["Recommendation",Boolean(state.recommendation)],["Operator decision",Boolean(state.recommendation?.approval)||state.recommendation?.requires_approval===false],["Action recorded",state.action?.status==="completed"],["Follow-up evaluated",Boolean(state.verification)],["Case resolved",d?.case?.status==="resolved"]];const current=steps.findIndex(([,done])=>!done);return `<ol class="history-strip">${steps.map(([label,done],i)=>`<li class="${done?"done":i===current?"current":"future"}"><span>${done?"✓":i+1}</span><small>${esc(label)}</small></li>`).join("")}</ol>`;}

function liveRecommendation(d){const current=currentRecommendation(d);if(!current)return '<div class="empty-state"><strong>No action recommended yet</strong><p>A recommendation will appear only after the evidence has been compared.</p></div>';const action=d.actions.find(a=>a.recommendation_id===current.id),title=human(current.action_type),state=currentWorkflow(d);return `<div class="recommendation"><div class="recommendation-head"><div><h3>${esc(title)}</h3><p>${esc(current.rationale)}</p></div>${badge(current.risk)}</div><div class="safety-callout"><strong>${esc(state.title)}</strong><p>${esc(state.help)} Actions are simulated; no field equipment is controlled.</p></div><dl class="plain-facts"><dt>What it will do</dt><dd>Record an approved simulated inspection for this case.</dd><dt>What it will not do</dt><dd>It will not control a meter, transformer, or field device.</dd></dl><div id="live-workflow-controls"></div>${action?.status==="superseded"?'<p class="report-alert">This action is no longer current and cannot be executed.</p>':""}</div>`;}
function demoGuide(){const steps=[["Reading arrives","Prepared meter readings enter the same event pipeline used by the investigation."],["Anomaly detected","Validated thresholds distinguish the unusual reading from normal variation."],["Evidence gathered","Meter history, peers, topology, transformer balance, and available context are checked."],["Explanations compared","Competing explanations gain or lose support as stored evidence changes."],["Next step proposed","A recommendation is tied to the evidence and its limitations."],["Operator decides","Consequential simulated actions remain blocked until a person approves them."],["Outcome checked","Follow-up readings determine whether the case resolves, reopens, or keeps monitoring."]];return `<details class="demo-guide"><summary><span><strong>How this demonstration works</strong><small>Seven evidence-led steps, with a human kept in control</small></span><span class="guide-chevron" aria-hidden="true">⌄</span></summary><div class="guide-body"><ol class="guide-journey">${steps.map(([title,copy],index)=>`<li><span>${index+1}</span><div><strong>${esc(title)}</strong><small>${esc(copy)}</small></div></li>`).join("")}</ol><nav class="guide-shortcuts" aria-label="Demonstration guide shortcuts"><button type="button" class="guide-link" data-guide-target="live-activity">View investigation activity</button><button type="button" class="guide-link" data-guide-target="live-evidence">View evidence</button><button type="button" class="guide-link" data-guide-target="live-hypotheses">View explanations</button><button type="button" class="guide-link" data-guide-target="live-recommendation">View recommendation</button></nav><div class="guide-facts"><article><h3>Why is it agentic?</h3><p>A reading event starts the workflow. MeterDetective selects meaningful evidence checks, stores why they were used, and can revise the same case when new evidence contradicts the earlier plan.</p></article><article><h3>What data is synthetic?</h3><p>The demonstration scenarios use synthetic readings, topology, and tariff inputs for repeatability. Technical guidance and weather evidence are labeled with their source and freshness.</p></article><article><h3>How is uncertainty handled?</h3><p>Confidence means current evidence support, not proof. Missing evidence stays Unknown, and contradictory evidence remains visible.</p></article><article><h3>What happens when a service fails?</h3><p>An optional evidence failure is recorded and the investigation continues when safe. If the database is unavailable, the workflow stops because its audit history cannot be preserved.</p></article></div><p class="guide-boundary"><strong>Simulation only:</strong> approvals and actions are recorded for demonstration. MeterDetective does not control field equipment.</p></div></details>`;}
function focusGuideTarget(id){const target=document.getElementById(id);if(!target)return false;target.setAttribute("tabindex","-1");target.scrollIntoView?.({behavior:"smooth",block:"start"});target.focus({preventScroll:true});return true;}
function renderLive(){if((location.hash||"#/live")!=="#/live")return;const key=liveFormKey(live.detail);if(main.dataset.liveFormKey===key&&main.querySelector("#play-demo")){updateLivePassive(live.detail);return;}main.dataset.liveFormKey=key;const forms=captureForms();setNavigation("live");const d=live.detail,[phaseTitle,phaseHelp]=livePhase(),summary=liveSummary(d),playing=busy&&["playing_normal_readings","investigating_initial_anomaly","waiting_for_related_readings","updating_existing_case"].includes(live.phase),canReset=!busy,reference=d?`${d.meter_ids.length} affected meter${d.meter_ids.length===1?"":"s"}`:investigationPresence();main.innerHTML=`<div class="live-title"><div><div class="kicker">MONITOR · INVESTIGATE · EXPLAIN</div><h1>${esc(liveHeading())}</h1><p class="subtitle">Watch meter evidence arrive, see how explanations change, and keep consequential actions under human control.</p></div><div class="case-reference">${esc(reference)}</div></div><section class="demo-control" aria-labelledby="demo-title"><div><h2 id="demo-title">${esc(phaseTitle)}</h2><p>${esc(phaseHelp)}</p></div><div class="demo-actions">${live.caseId?`<button id="refresh-live" ${busy?"disabled":""}>Refresh case</button>`:""}<button class="primary" id="play-demo" ${busy?'disabled aria-disabled="true"':""}>${playing?"Stream playing…":"Play demonstration stream"}</button><button id="reset-demo" ${canReset?"":'disabled aria-disabled="true"'}>Reset demonstration</button></div><div class="progress-wrap"><div class="progress-label"><span>${live.progress?`Reading ${live.progress} of ${live.total}`:live.caseId?"Earlier replay progress unavailable":"Stream not started"}</span><span>${Math.round(live.progress/live.total*100)}%</span></div><div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="9" aria-valuenow="${live.progress}"><span style="width:${live.progress/live.total*100}%"></span></div></div><div id="live-replay-error">${live.error?`<div class="error inline-error" role="alert"><strong>The replay stopped safely.</strong><p>${esc(live.error)}</p><p>Reset the demonstration and try again. Existing historical cases were not removed.</p></div>`:""}</div></section><div id="live-refresh-status">${live.refreshError?`<div class="report-alert" role="status">Refresh unavailable: ${esc(live.refreshError)}. Showing the last stored case state; reload before another action.</div>`:""}</div><div class="readiness" aria-label="Demonstration readiness">${[["Database",live.ready||Boolean(d)],["Scenario data",live.ready||Boolean(d)],["Investigation workflow",Boolean(d)],["Recommendation recorded",Boolean(currentRecommendation(d))]].map(([label,ready])=>`<span class="readiness-item ${ready?"ready":"waiting"}"><b aria-hidden="true">${ready?"✓":"○"}</b>${esc(label)} · ${ready?"Ready":"Waiting"}</span>`).join("")}</div>${demoGuide()}<div class="stats live-stats">${summary.map(([label,value,note])=>`<div class="stat"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`).join("")}</div><div class="live-grid"><div><section class="panel"><div class="panel-body"><div class="panel-heading"><div><h2>Meter reading stream</h2><p>Observed consumption and investigation triggers, shown in UTC.</p></div></div><div id="chart" class="live-chart">${d?'Loading the latest readings…':'The reading chart will appear when an investigation starts.'}</div><div id="live-stream">${liveStream()}</div></div></section>${panel("Investigation activity",liveActivity(),"live-activity")}${panel("Evidence and investigation details",liveEvidence(d),"live-evidence")}</div><div>${panel("Competing explanations",liveHypotheses(d),"live-hypotheses")}${panel("Investigation plan",livePlans(d),"live-plan")}${panel("Recommended next step",liveRecommendation(d),"live-recommendation")}</div></div>${panel("Case history",liveHistory(d),"live-history")}`;const refresh=document.getElementById("refresh-live");if(refresh)refresh.onclick=()=>route();document.getElementById("play-demo").onclick=playLiveDemo;document.getElementById("reset-demo").onclick=confirmResetLive;if(d){loadChart(d,generation);const current=currentRecommendation(d);if(current)workflowControls(d,current,"live-workflow-controls");}restoreForms(forms);if(busy||refreshRequired)main.querySelectorAll("button").forEach(b=>b.disabled=busy||b.id!=="refresh-live");}
function addStream(stage,meter,result){const abnormal=result.anomaly_count>0,time=stage==="shared"?"2026-09-21 12:30":stage==="initial"?"2026-09-21 12:00":"2026-09-21 11:30";live.stream.push({meter,time,label:abnormal?"Anomaly evidence recorded":result.status==="normal"?"Reading within expected range":"Reading processed",kind:abnormal?"anomaly":"normal",value:result.case_id?(result.duplicate?"Existing event already processed":"Investigation evidence recorded"):human(result.status)});}

async function refreshLiveCase(token=generation){
  if(!live.caseId)return;
  const id=live.caseId,request=++liveRequest;refreshingLive=true;
  try{
    const detail=await api(`/cases/${encodeURIComponent(id)}`);
    if(id!==live.caseId||token!==generation||request!==liveRequest)return;
    const changed=JSON.stringify(detail)!==JSON.stringify(live.detail)||refreshRequired||Boolean(live.refreshError);live.detail=detail;refreshRequired=false;live.refreshError=null;
    if(changed)renderLive();
    try{const trace=await api(`/cases/${encodeURIComponent(id)}/trace`);if(id!==live.caseId||token!==generation||request!==liveRequest)return;live.trace=trace;const target=document.getElementById("live-activity");if(target)updatePassive("#live-activity .panel-body",'<h2>Investigation activity</h2>'+liveActivity());}catch(error){notice(`Activity trace unavailable: ${error.message}`,true);}
  }finally{if(request===liveRequest)refreshingLive=false;}
}

async function playStage(stage,phase){live.phase=phase;renderLive();const results=await api("/replay/scenario-2/replay",{stage});for(let i=0;i<results.length;i++){const result=results[i];if(result.case_id){live.caseId=result.case_id;sessionStorage.setItem("meterdetective-live-case",result.case_id);}addStream(stage,DEMO_METERS[i],result,i);live.progress=Math.min(live.total,live.progress+1);saveLivePlayback();renderLive();await wait(180);}if(live.caseId)await refreshLiveCase();if(results.some(result=>result.status==="failed"))throw Error("A reading investigation failed. Review the stored evidence before continuing.");return results;}
async function playLiveDemo(){if(busy)return;busy=true;++generation;++liveRequest;live={phase:"resetting",progress:0,total:DEMO_TOTAL,caseId:null,detail:null,trace:null,stream:[],error:null,ready:false};renderLive();try{await api("/replay/scenario-2/reset",{});sessionStorage.removeItem("meterdetective-live-case");sessionStorage.removeItem("meterdetective-live-playback");live.ready=true;await playStage("normal","playing_normal_readings");await playStage("initial","investigating_initial_anomaly");live.phase="waiting_for_related_readings";renderLive();await wait(550);await playStage("shared","updating_existing_case");live.phase="complete";saveLivePlayback();busy=false;renderLive();document.querySelector(".plan-change")?.focus();notice(livePhase().join(". "));if((location.hash||"#/live")!=="#/live")await route();}catch(error){busy=false;live.phase="failed";live.error=error.message;renderLive();if((location.hash||"#/live")!=="#/live")await route();}}
function confirmResetLive(){if(busy)return;if(!window.confirm("Reset the demonstration? This removes only demonstration cases and readings. Historical reference cases are preserved."))return;resetLiveOnly();}
async function resetLiveOnly(){busy=true;++generation;++liveRequest;live.phase="resetting";live.error=null;renderLive();try{await api("/replay/scenario-2/reset",{});sessionStorage.removeItem("meterdetective-live-case");sessionStorage.removeItem("meterdetective-live-playback");live={phase:"ready",progress:0,total:DEMO_TOTAL,caseId:null,detail:null,trace:null,stream:[],error:null,ready:true};busy=false;renderLive();notice("The demonstration is ready. Historical reference cases were preserved.");}catch(error){busy=false;live.phase="failed";live.error=error.message;renderLive();}}
function renderQueue(){const history=queueView==="history";const toggle=history?`← Operational investigations (${queueMeta.investigated_total})`:`Historical cases (${queueMeta.legacy_total})`;main.innerHTML=`<div class="title-row"><div><div class="kicker">${history?"REFERENCE · IMPORTED · PRESERVED":"INVESTIGATE · REVIEW · RESOLVE"}</div><h1>${history?"Historical cases":"Case queue"}</h1><p class="subtitle">${history?"Imported records retained for audit history and precedent matching.":"Your investigated priorities, backed by meter evidence."}</p></div><div class="actions"><button id="view-toggle">${toggle}</button>${history?"":'<button id="reset-scenario">Reset & run Scenario 1</button>'}<button id="refresh">↻ Refresh</button></div></div><div class="stats" id="stats"></div><section class="panel"><div class="toolbar"><input id="search" type="search" aria-label="Search cases or meters" placeholder="Search cases or meter IDs" value="${esc(filters.search)}"><select id="status" aria-label="Filter status"><option value="">All statuses</option>${[...new Set(queueItems.map(x=>x.status))].sort().map(s=>`<option value="${esc(s)}" ${filters.status===s?"selected":""}>${esc(human(s))}</option>`).join("")}</select><select id="priority" aria-label="Filter priority"><option value="">All priorities</option>${["P1","P2","P3","P4"].map(p=>`<option ${filters.priority===p?"selected":""}>${p}</option>`).join("")}</select><select id="sort" aria-label="Sort cases">${[["priority","Priority / rank"],["status","Status"],["anomaly","Anomaly type"],["confidence","Evidence support"],["meters","Affected meters"],["age","Oldest first"],["updated","Recently updated"]].map(([v,t])=>`<option value="${v}" ${filters.sort===v?"selected":""}>${t}</option>`).join("")}</select></div><div class="table-wrap"><table><thead><tr><th>Priority / rank</th><th>Case / meters</th><th>Status</th><th>Revenue at risk</th><th>Evidence support</th><th>Report</th><th>Age</th></tr></thead><tbody id="queue-body"></tbody></table></div><div class="pager" id="count"></div></section><p class="chart-note">${history?"Historical records remain searchable by the precedent engine. Missing investigation answers are never fabricated.":"Reset replaces only the synthetic Scenario 1 slice. Historical imports are preserved. Queue refreshes every 10 seconds while visible."}</p>`;document.getElementById("refresh").onclick=()=>route();document.getElementById("view-toggle").onclick=()=>{queueView=history?"investigations":"history";filters.status="";filters.priority="";route();};const reset=document.getElementById("reset-scenario");if(reset)reset.onclick=resetScenario;for(const name of ["search","status","priority","sort"]){document.getElementById(name).addEventListener(name==="search"?"input":"change",e=>{filters[name]=e.target.value;renderRows();});}renderRows();}
function renderRows(){const history=queueView==="history",active=queueItems.filter(x=>!["resolved","closed"].includes(x.status));const stats=history?[["Historical records",queueItems.length],["Closed",queueItems.filter(x=>x.status==="closed").length],["Linked meters",queueItems.reduce((n,x)=>n+x.meter_ids.length,0)],["Operational investigations",queueMeta.investigated_total]]:[["Active investigations",active.length],["Needs approval",queueItems.filter(x=>x.status==="awaiting_approval").length],["Critical · P1",active.filter(x=>x.priority_band==="P1").length],["Historical imports",queueMeta.legacy_total]];document.getElementById("stats").innerHTML=stats.map(([label,n])=>`<div class="stat"><span>${label}</span><strong>${n}</strong></div>`).join("");const rows=queueItems.filter(x=>(!filters.status||x.status===filters.status)&&(!filters.priority||x.priority_band===filters.priority)&&`${x.title} ${x.meter_ids.join(" ")}`.toLowerCase().includes(filters.search.toLowerCase()));rows.sort((a,b)=>{if(filters.sort==="status")return a.status.localeCompare(b.status);if(filters.sort==="anomaly")return (a.anomaly_type||"~").localeCompare(b.anomaly_type||"~");if(filters.sort==="meters")return b.meter_ids.length-a.meter_ids.length;if(filters.sort==="confidence")return (b.confidence??-1)-(a.confidence??-1);if(filters.sort==="age")return a.opened_at.localeCompare(b.opened_at);if(filters.sort==="updated")return b.updated_at.localeCompare(a.updated_at);return (a.priority_band||"P9").localeCompare(b.priority_band||"P9")||(a.active_rank??999999)-(b.active_rank??999999);});document.getElementById("queue-body").innerHTML=rows.map(x=>{const investigated=x.report_version!==null;return `<tr><td>${badge(x.priority_band)} <small>${x.active_rank?`Rank #${x.active_rank}`:"Unranked"}</small></td><td><a class="case-title" href="#/cases/${esc(x.id)}">${esc(x.title)}</a><small>${esc(x.meter_ids.join(", ")||"No meter linked")} · ${esc(investigated?human(x.anomaly_type):"Historical import")}</small></td><td>${badge(x.status)}<small>${investigated?(x.precedent_count===null?"Precedents unknown":`${x.precedent_count} precedent(s)`):"Available as precedent"}</small></td><td>${investigated?money(x.revenue_jod?.base):"Historical record"}<small>${investigated?(x.revenue_jod?`${money(x.revenue_jod.low)} – ${money(x.revenue_jod.high)}`:"Awaiting financial evidence"):"No agent calculation"}</small></td><td>${investigated?percent(x.confidence):"—"}</td><td>${investigated?`${x.answered_count}/18 answered<small>${x.present_count}/18 present · v${x.report_version}</small>`:"Not investigated<small>Historical import</small>"}</td><td>${age(x.opened_at)}<small>${esc(date(x.updated_at))}</small></td></tr>`;}).join("")||'<tr><td colspan="7" class="empty">No cases match these filters.</td></tr>';document.getElementById("count").textContent=`${rows.length} of ${queueItems.length} ${history?"historical cases":"investigations"}`;}
function questionPanel(answers,d){return questions.map((title,i)=>{const a=answers.get(i+1);return `<details class="question"><summary><span class="q-number">${String(i+1).padStart(2,"0")}</span><strong>${esc(title)}</strong>${badge(a?.status||"missing")}</summary>${a?`<p>${i===13?esc(currentWorkflow(d).title+". "+currentWorkflow(d).help):i===10?"Current evidence support: "+percent(a.structured_values?.confidence??a.confidence)+". Evidence support is not proof of root cause.":esc(a.answer)}</p><p class="chart-note">Report evidence support ${percent(a.confidence)} · Fresh as of ${esc(date(a.fresh_as_of))}</p><p>Supporting evidence: ${references(a.supporting_evidence)}</p><p>Contradicting evidence: ${references(a.contradicting_evidence)}</p>${(a.limitations||[]).map(l=>`<p class="muted">${esc(l)}</p>`).join("")}<details><summary>Stored report snapshot (may predate the operator decision)</summary>${json(a.structured_values)}</details>`:'<p class="muted">This question is missing from the persisted report.</p>'}</details>`;}).join("");}
function renderDetail(d){const c=d.case,a=answerMap(d),current=currentRecommendation(d),coverage=d.report_coverage||{};if(!coverage.has_report){renderLegacyDetail(d);return;}const reportNotice=coverage.missing_question_ids?.length?`<div class="report-alert"><strong>Incomplete report</strong><p>Missing questions: ${esc(coverage.missing_question_ids.join(", "))}</p></div>`:`<div class="coverage-ok">18/18 question slots persisted · ${coverage.answered_count}/18 currently answered</div>`;main.innerHTML=`<a href="#/cases">← Case queue</a><div class="title-row"><div><div class="kicker">${d.scenario?"SCENARIO 1 · ":""}CASE ${esc(c.id.slice(0,8))}</div><h1>${esc(c.title)}</h1><div class="facts">${badge(c.status)}${badge(c.priority_band)}<span>Current evidence support: ${percent(c.confidence)}</span><span>${esc(d.meter_ids.join(", ")||"No meters linked")}</span><span>Report v${d.latest_report.version}</span></div></div><button id="refresh">↻ Refresh</button></div><nav class="section-nav">${[["report","18 questions"],["evidence","Evidence"],["hypotheses","Hypotheses"],["trace","Agent trace"],["history","History"]].map(([id,t])=>`<a href="#${id}" data-section="${id}">${t}</a>`).join("")}</nav><div class="detail-grid"><div>${panel("Consumption around the incident",'<div id="chart" role="status">Loading readings…</div>')}${panel("Investigation report",reportNotice+questionPanel(a,d),"report")}${panel("Evidence timeline",d.evidence.map(e=>`<div class="timeline-item" id="evidence-${esc(e.id)}"><small>${esc(date(e.created_at))} · Reliability ${percent(e.reliability)}</small><h3>${esc(human(e.kind))}</h3><p class="muted">${esc(e.source)}</p><details><summary>Inspect evidence</summary>${json(e.value)}</details></div>`).join("")||'<p class="muted">No evidence recorded.</p>',"evidence")}${panel("Agent execution trace",'<div id="trace-content">Loading trace…</div>',"trace")}</div><div>${panel("Current recommendation",current?`<h3>${esc(human(current.action_type))}</h3><p>${esc(current.rationale)}</p>${badge(current.status)} <span class="muted">${esc(current.risk)} risk</span><p>${esc(currentWorkflow(d).title)}</p><div id="workflow-controls"></div>`:'<p class="muted">No recommendation has been recorded.</p>')}${panel("Financial exposure",financial(d,a.get(16)))}${panel("Competing hypotheses",hypotheses(d))}${panel("Precedents",precedents(d,a.get(17)))}${panel("Triage assessment",triage(d,a.get(18)))}${panel("Verification outcome",outcome(currentWorkflow(d).verification?a.get(15):null))}${panel("Document citations",citations(d))}${panel("Case history",d.case_events.map(e=>`<div class="timeline-item"><small>${esc(date(e.created_at))}</small><h3>${esc(human(e.event_type))}</h3><details><summary>Event details</summary>${json(e.details)}</details></div>`).join("")||'<p class="muted">No case events recorded.</p>',"history")}</div></div>`;document.getElementById("refresh").onclick=()=>route();main.querySelectorAll("[data-section],[data-evidence]").forEach(link=>link.onclick=e=>{e.preventDefault();const id=link.dataset.section||`evidence-${link.dataset.evidence}`;const target=document.getElementById(id);if(target)target.scrollIntoView({behavior:"smooth"});else notice("Referenced evidence is not part of this case view.");});if(current)workflowControls(d,current);}
function renderLegacyDetail(d){const c=d.case;main.innerHTML=`<a href="#/cases">← Historical cases</a><div class="title-row"><div><div class="kicker">HISTORICAL IMPORT · CASE ${esc(c.id.slice(0,8))}</div><h1>${esc(c.title)}</h1><div class="facts">${badge(c.status)}${badge(c.priority_band)}<span>${esc(d.meter_ids.join(", ")||"No meters linked")}</span><span>Report unavailable</span></div></div><button id="refresh">↻ Refresh</button></div><div class="detail-grid"><div>${panel("Historical case record",'<div class="report-alert"><strong>Not agent-investigated</strong><p>This record predates the 18-question investigation workflow. It remains available as precedent evidence; no answers, evidence, financial calculations, or agent trace have been fabricated.</p></div>')}${panel("Linked meters",d.meter_ids.length?`<p>${esc(d.meter_ids.join(", "))}</p>`:'<p class="muted">No meters are linked to this imported record.</p>')}</div><div>${panel("Record status",`<dl><dt>Status</dt><dd>${esc(human(c.status))}</dd><dt>Priority</dt><dd>${esc(c.priority_band||"Unavailable")}</dd><dt>Opened</dt><dd>${esc(date(c.opened_at))}</dd><dt>Updated</dt><dd>${esc(date(c.updated_at))}</dd></dl>`)}${panel("Case history",d.case_events.map(e=>`<div class="timeline-item"><small>${esc(date(e.created_at))}</small><h3>${esc(human(e.event_type))}</h3><details><summary>Event details</summary>${json(e.details)}</details></div>`).join("")||'<p class="muted">No case events were included in the import.</p>')}</div></div>`;document.getElementById("refresh").onclick=()=>route();}
function answerSummary(a){return a?`${badge(a.status)}<p>${esc(a.answer)}</p>${(a.limitations||[]).map(l=>`<p class="muted">${esc(l)}</p>`).join("")}<details><summary>Calculation details</summary>${json(a.structured_values)}</details>`:'<p class="muted">No assessment recorded.</p>';}
function evidenceLinks(ids){return (ids||[]).map(id=>`<a href="#evidence-${esc(id)}" data-evidence="${esc(id)}">${esc(String(id).slice(0,8))}</a>`).join(", ")||"None";}
function hypotheses(d){return d.hypotheses.map(h=>`<div class="hypothesis"><h3>${esc(human(h.label))}</h3><span class="muted">Current evidence support: ${percent(h.confidence)} · not proof of root cause</span><div class="confidence"><span style="width:${Math.max(0,Math.min(100,h.confidence*100))}%"></span></div><p class="compact"><strong>Supports:</strong> ${evidenceLinks(h.supporting_evidence)}</p><p class="compact"><strong>Contradicts:</strong> ${evidenceLinks(h.contradicting_evidence)}</p><details><summary>Confidence history</summary>${json(h.update_history)}</details></div>`).join("")||'<p class="muted">No hypotheses recorded.</p>';}
function financial(d,a){const f=d.financial_impact;if(!f)return `<p class="muted">Financial exposure is unknown because no valid financial-impact record exists for this report.</p>${answerSummary(a)}`;return `<div class="money">${money(f.risk_jod.base)}</div><p class="muted">Low ${money(f.risk_jod.low)} · High ${money(f.risk_jod.high)}</p><dl class="metrics"><dt>Missing energy</dt><dd>${fixed(f.missing_kwh.low,2)} / ${fixed(f.missing_kwh.base,2)} / ${fixed(f.missing_kwh.high,2)} kWh</dd><dt>Tariff</dt><dd>${esc(f.tariff?.name||"Unavailable")} · ${f.tariff?`${fixed(f.tariff.jod_per_kwh,3)} JOD/kWh`:""}</dd><dt>Confidence</dt><dd>${percent(f.confidence)}</dd><dt>Source</dt><dd>${esc(f.tariff?.source||"Unavailable")}</dd></dl><details><summary>Assumptions</summary>${json(f.assumptions)}</details>`;}
function precedents(d,a){if(!d.precedents?.length)return answerSummary(a);return `${d.precedents.map(p=>`<div class="precedent"><strong>${esc(p.title)}</strong><p>${badge(p.status)} ${esc(human(p.match_type))}${p.outcome?` · Outcome ${esc(p.outcome)}`:""}</p><a href="#/cases/${esc(p.case_id)}">Open prior case →</a></div>`).join("")}<details><summary>Question 17 details</summary>${answerSummary(a)}</details>`;}
function triage(d,a){const t=d.triage_assessment;if(!t)return answerSummary(a);const inactive=["resolved","closed"].includes(d.case.status);return `${inactive?'<p class="coverage-ok">Resolved cases are no longer ranked. Historical pre-resolution assessment:</p>':""}<div class="triage-score">${t.band} <strong>${fixed(t.score,1)}</strong><span>/100</span></div><p>${inactive?"Historical rank":"Rank"} <strong>${esc(t.active_rank??"Unknown")}</strong> of ${esc(t.active_count??"Unknown")} cases · ${fixed(t.percentile,1)} percentile</p><p class="muted">Policy ${esc(t.policy_version)} · ${esc(date(t.calculated_at))}</p><details><summary>Factor breakdown</summary>${json(t.factors)}</details>`;}
function outcome(a){if(!a)return '<p class="muted">No verification assessment recorded.</p>';const v=a.structured_values||{};return `${badge(v.deterministic_status||a.status)}<p>${esc(a.answer)}</p>${v.outcome||v.status?`<dl class="metrics"><dt>Outcome</dt><dd>${esc(human(v.outcome||v.status))}</dd><dt>Window</dt><dd>${esc(date(v.window_start))} → ${esc(date(v.window_end))}</dd><dt>Observations</dt><dd>${esc(v.valid_observation_count??"Unknown")} valid of ${esc(v.observation_count??"Unknown")}</dd><dt>Expected / observed</dt><dd>${esc(v.expected_kwh??"Unknown")} / ${esc(v.observed_kwh??"Unknown")} kWh</dd><dt>Baseline recovery</dt><dd>${percent(v.within_baseline_fraction)}</dd><dt>Peer agreement</dt><dd>${percent(v.peer_agreement_fraction)}</dd></dl>`:""}${(a.limitations||[]).map(l=>`<p class="muted">${esc(l)}</p>`).join("")}<details><summary>Complete verification record</summary>${json(v)}</details>`;}
function citations(d){return (d.citations||[]).map(x=>`<div class="citation"><a href="${esc(x.source_url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a>${x.section?`<small>Section ${esc(x.section)}</small>`:""}${x.license?`<small>License ${esc(x.license)}</small>`:""}</div>`).join("")||'<p class="muted">No linked documents were retrieved.</p>';}
function localInput(value){const timestamp=value?utcDate(value):null;return timestamp&&Number.isFinite(+timestamp)?timestamp.toISOString().slice(0,16):"";}

function workflowControls(d,r,rootId="workflow-controls"){const root=document.getElementById(rootId),action=d.actions.find(x=>x.recommendation_id===r.id);if(!root)return;const prefix=(rootId==="workflow-controls"?"case":"live")+"-"+r.id;if(currentWorkflow(d).approvalPending){root.innerHTML=`<form class="form" id="${prefix}-decision"><label>Operator name <input name="operator" required maxlength="120" autocomplete="name"></label><label>Comment <textarea name="comment" maxlength="10000" placeholder="Optional for approval; recommended when rejecting"></textarea></label><div class="actions"><button class="primary" value="approve">Approve simulated action</button><button class="danger" value="reject">Reject recommendation</button></div></form><p class="chart-note">The operator name is recorded for this demonstration; it is not an authenticated identity.</p>`;document.getElementById(`${prefix}-decision`).onsubmit=e=>{e.preventDefault();const form=e.target,operator=form.operator.value.trim();if(!operator){form.operator.focus();return;}mutate(`/recommendations/${r.id}/${e.submitter?.value||"approve"}`,{decided_by:operator,comment:form.comment.value.trim()||null},"Decision recorded.");};}else if(action?.status==="ready"&&(!r.requires_approval||r.approval?.decision==="approved")){const scenario=Boolean(d.scenario);root.innerHTML=`<p class="chart-note">${scenario?"Adds deterministic post-repair readings for Scenario 1. The action and inserted window remain auditable.":"Records an approved simulated inspection. No meter or network equipment will be controlled."}</p><button class="primary" id="${prefix}-simulate">${scenario?"Apply simulated repair":"Record simulated inspection"}</button>`;document.getElementById(`${prefix}-simulate`).onclick=()=>mutate(`/actions/${action.id}/execute-simulation`,{result:{simulation:true,source:"case_dashboard",description:scenario?"Scenario 1 simulated repair requested.":"Operator recorded simulated action; readings unchanged."}},scenario?"Simulated repair applied. The verification window is ready.":"Simulated inspection recorded. Follow-up readings are required to verify the outcome.");}else if(action?.status==="completed"){const window=verificationWindow(d,action);const complete=["resolved","closed"].includes(d.case.status);root.innerHTML=`<p>${r.approval?.decision==="approved"?"Approved simulated action recorded":"Simulated action recorded"} ${esc(date(action.executed_at))}</p>${complete&&currentWorkflow(d).verification?outcome(answerMap(d).get(15)):""}${complete?`<p class="coverage-ok">The case is ${esc(human(d.case.status))}.</p>`:`${window.start&&window.end?'<p class="chart-note">Stored demo follow-up window prefilled. These are inputs only; the verification engine determines the outcome.</p>':'<p class="report-alert">No stored follow-up window is available. This simulated inspection did not add readings. Supply an observed follow-up window before verification.</p>'}<div id="${prefix}-verification-result">${currentWorkflow(d).verification?outcome(answerMap(d).get(15)):""}</div><form class="form" id="${prefix}-verify"><label>Observation start (UTC)<input type="datetime-local" name="start" value="${esc(localInput(window.start))}" required></label><label>Observation end (UTC)<input type="datetime-local" name="end" value="${esc(localInput(window.end))}" required></label><button class="primary">Check follow-up readings</button></form>`}`;if(!complete)document.getElementById(`${prefix}-verify`).onsubmit=e=>{e.preventDefault();const f=e.target,start=new Date(f.start.value+"Z"),end=new Date(f.end.value+"Z");if(!Number.isFinite(+start)||!Number.isFinite(+end)||end<=start){notice("Enter valid UTC timestamps; end must be after start.",true);return;}mutate(`/cases/${d.case.id}/verify`,{action_id:action.id,window_start:start.toISOString(),window_end:end.toISOString()},"Follow-up check recorded.");};}else{root.innerHTML=`<p class="muted">${r.approval?`Decision: ${esc(r.approval.decision)} by ${esc(r.approval.decided_by)}. ${esc(r.approval.comment||"")}`:"This recommendation is not awaiting an operator decision."}</p>`;}}
async function resetScenario(){if(busy)return;busy=true;main.querySelectorAll("button").forEach(button=>button.disabled=true);notice("Resetting and investigating Scenario 1…");try{const result=await api("/replay/reset",{});busy=false;location.hash=`#/cases/${result.case_id}`;await route();notice("Scenario 1 reset completed. Review the new investigation and approval request.");}catch(error){busy=false;notice(error.message,true);main.querySelectorAll("button").forEach(button=>button.disabled=false);}}
async function mutate(path,body,message){
  if(busy||refreshRequired)return;busy=true;++generation;
  main.querySelectorAll("button").forEach(button=>button.disabled=true);
  let accepted=false;
  try{
    const response=await api(path,body);accepted=true;refreshRequired=true;applyWorkflowResponse(live.detail,response);if((location.hash||"#/live")==="#/live")renderLive();notice(message);
    // Until fresh authoritative state arrives, stale mutation controls stay disabled.
    if((location.hash||"#/live")==="#/live"&&live.caseId){await refreshLiveCase();busy=false;renderLive();}
    else {busy=false;await route();refreshRequired=false;}
  }catch(error){
    live.refreshError=error.message;notice(accepted?`Change recorded; refresh unavailable: ${error.message}. Refresh before another action.`:error.message,true);
    refreshRequired=true;
    workflowRefreshWarning(accepted?"Change recorded. Reload the case before another action.":"Request did not return a confirmed result. Reload the case to check its stored state before retrying.");
  }finally{busy=false;}
}

async function loadTrace(id,token){try{const data=await api(`/cases/${encodeURIComponent(id)}/trace`);if(token!==generation||!document.getElementById("trace-content"))return;document.getElementById("trace-content").innerHTML=data.runs.map(run=>`<details class="trace-run"><summary>${badge(run.status)} Run ${esc(run.id.slice(0,8))} · ${esc(date(run.started_at))} · ${run.tools.length} calls</summary>${run.tools.map(t=>`<details class="trace-tool"><summary>${esc(t.name)} · ${esc(t.status)} · ${t.latency_ms} ms</summary><h3>Input</h3>${json(t.input)}<h3>Output</h3>${json(t.output)}${t.error?`<h3>Failure</h3>${json(t.error)}`:""}</details>`).join("")}</details>`).join("")||'<p class="muted">No agent runs recorded.</p>';}catch(e){if(token===generation&&document.getElementById("trace-content"))document.getElementById("trace-content").textContent=`Trace unavailable: ${e.message}`;}}
async function loadChart(d,token){const target=document.getElementById("chart"),time=answerMap(d).get(1)?.fresh_as_of,meter=d.meter_ids[0];if(!meter||!time){target.textContent="No incident timestamp or linked meter is available for a reading chart.";return;}try{const event=utcDate(time),start=new Date(+event-24*3600000),end=new Date(+event+24*3600000);const data=await api(`/meters/${encodeURIComponent(meter)}/readings?start=${encodeURIComponent(start.toISOString())}&end=${encodeURIComponent(end.toISOString())}&limit=1000`);if(document.getElementById("chart")!==target)return;const points=data.items.filter(p=>Number.isFinite(p.kwh));if(!points.length){target.textContent="No readings in the incident window.";return;}const max=Math.max(...points.map(p=>p.kwh),.01),x=t=>45+(utcDate(t)-start)/(end-start)*700,y=v=>175-v/max*150;const path=points.map((p,i)=>`${i?"L":"M"}${x(p.timestamp)},${y(p.kwh)}`).join(" ");target.innerHTML=`<svg class="reading-chart" viewBox="0 0 790 215" role="img" aria-label="${esc(meter)} consumption readings around the incident"><line x1="45" y1="175" x2="745" y2="175" stroke="var(--chart-grid)"/><line x1="${x(event)}" x2="${x(event)}" y1="20" y2="175" stroke="var(--chart-event)" stroke-dasharray="4"/><path d="${path}" fill="none" stroke="var(--chart-line)" stroke-width="2"/><text x="5" y="30" font-size="11" fill="var(--muted)">${max.toFixed(1)}</text><text x="20" y="178" font-size="11" fill="currentColor">0</text><text x="45" y="201" font-size="11" fill="currentColor">−24h</text><text x="${x(event)-18}" y="201" font-size="11" fill="currentColor">Incident</text><text x="710" y="201" font-size="11" fill="currentColor">+24h</text></svg><p class="chart-note">${esc(meter)} · kWh · ${points.length} observations. Dashed marker: incident. ${d.meter_ids.length>1?"First affected meter shown.":""}</p>`;}catch(e){if(document.getElementById("chart")===target)target.textContent=`Readings unavailable: ${e.message}`;}}
document.querySelector(".skip").addEventListener("click", event => {
  event.preventDefault();
  main.focus();
});
initializeTheme();
main.addEventListener("click", event => {
  const guideLink=event.target.closest("[data-guide-target]");
  if(guideLink)focusGuideTarget(guideLink.dataset.guideTarget);
  const control=event.target.closest("button");
  if(control?.id==="play-demo")playLiveDemo();
  if(control?.id==="reset-demo")confirmResetLive();
});
window.addEventListener("hashchange",()=>route());
setInterval(()=>{if(!document.hidden&&!location.hash.match(/^#\/cases\//)&&!busy)route(true);},10000);
route();
